//! Player scores shared between the match threads of the Pixel Arena server.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};

pub type PlayerId = u32;

/// Clones share the same scores, so each match thread keeps its own handle.
#[derive(Clone, Default)]
pub struct Board {
    players: Arc<Mutex<HashMap<PlayerId, Arc<Mutex<i64>>>>>,
    total: Arc<Mutex<i64>>,
}

impl Board {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn join(&self, id: PlayerId, score: i64) {
        self.players.lock().unwrap().insert(id, Arc::new(Mutex::new(score)));
        *self.total.lock().unwrap() += score;
    }

    fn slot(&self, id: PlayerId) -> Arc<Mutex<i64>> {
        self.players.lock().unwrap()[&id].clone()
    }

    /// Adds points to a player and to the board total.
    pub fn award(&self, id: PlayerId, points: i64) {
        // Update each counter under a single lock: locking, reading, dropping
        // and re-locking would lose points when threads race here.
        *self.slot(id).lock().unwrap() += points;
        *self.total.lock().unwrap() += points;
    }

    /// Moves points between two players. The board total does not change.
    /// Moving points from a player to the same player changes nothing.
    pub fn transfer(&self, from: PlayerId, to: PlayerId, points: i64) {
        // `from == to` would lock the same mutex twice and hang the thread.
        if from == to {
            return;
        }
        // Lock the two slots in a fixed order (by player id). Otherwise two
        // opposite transfers running at once each hold the lock the other
        // one needs, and both threads hang waiting for each other.
        let (low, high) = if from < to { (from, to) } else { (to, from) };
        let low_slot = self.slot(low);
        let high_slot = self.slot(high);
        let mut low_score = low_slot.lock().unwrap();
        let mut high_score = high_slot.lock().unwrap();
        let (from_score, to_score) = if from < to {
            (&mut *low_score, &mut *high_score)
        } else {
            (&mut *high_score, &mut *low_score)
        };
        *from_score -= points;
        *to_score += points;
    }

    pub fn score(&self, id: PlayerId) -> i64 {
        *self.slot(id).lock().unwrap()
    }

    pub fn total(&self) -> i64 {
        *self.total.lock().unwrap()
    }
}

#[cfg(test)]
mod stress {
    use super::*;
    use std::thread;

    #[test]
    fn concurrent_awards_and_transfers_neither_hang_nor_lose_points() {
        const THREADS: u64 = 8;
        const ROUNDS: i64 = 2000;
        let board = Board::new();
        for id in 0..THREADS as PlayerId {
            board.join(id, 0);
        }
        let handles: Vec<_> = (0..THREADS)
            .map(|t| {
                let board = board.clone();
                thread::spawn(move || {
                    for _ in 0..ROUNDS {
                        board.award(t as PlayerId, 1);
                        // Opposite-direction transfers between the same two
                        // players run on every thread pair: the old code
                        // deadlocked here under load.
                        board.transfer(t as PlayerId, ((t + 1) % THREADS) as PlayerId, 2);
                        // Same-player transfer: the old code locked a
                        // non-reentrant mutex twice and hung forever.
                        board.transfer(t as PlayerId, t as PlayerId, 5);
                    }
                })
            })
            .collect();
        for h in handles {
            h.join().unwrap();
        }
        let sum_of_players: i64 = (0..THREADS as PlayerId).map(|id| board.score(id)).sum();
        assert_eq!(board.total(), THREADS as i64 * ROUNDS);
        assert_eq!(sum_of_players, board.total());
    }
}
